window.__posterData({"id": "nicole-jegardt", "name": "Nicole Velarde-Alvarez Jegardt", "folder": "PosterMedAI_NicoleJegardt_2026_10_30_15_29_18", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Färger och inställningar\nconst PARTICLE_COLORS = ['#cfff04', '#00ffff', '#00f2de', '#FD4499', '#39ff14', '#00FFFF'];\nconst DOT_COLORS = ['#cfff04', '#00ffff', '#00f2de', '#FD4499', '#39ff14'];\nconst NUM_PARTICLES = 120;\nconst MAX_MOUSE_DOTS = 25;\n\n\nconst TITLE_LINES = [\n  { color: 'yellow', y: 200 },\n  { color: 'lightblue', y: 235 },\n  { color: 'pink', y: 265 },\n  { color: 'limegreen', y: 295 },\n];\n\nlet particles = [];\nlet mouseDots = [];\nlet img;\n\nasync function setup() {\n  createCanvas(600, 800);\n  img = await loadImage('colorpicture.jpg');\n  describe('The text \"hyper\" written on several lines, each in a different color, waving and glowing like a neon sign.');\n\n  // Skapar partiklarna med slumpad position, storlek och färg\n  for (let i = 0; i < NUM_PARTICLES; i++) {\n    particles.push({\n      x: random(width),\n      y: random(height),\n      size: random(10, 50),\n      color: random(PARTICLE_COLORS),\n    });\n  }\n}\n\nfunction draw() {\n  image(img, 0, 0, width, height);\n  drawParticles();\n  drawMouseDots();\n  drawText();\n}\n\n// Ritar och flyttar partiklarna\nfunction drawParticles() {\n  noStroke();\n  particles.forEach((p, i) => {\n    fill(p.color);\n    ellipse(p.x, p.y, p.size);\n    p.x += sin(frameCount * 0.4 + i) * 5;\n    p.y += cos(frameCount * 0.02 + i) * 5;\n  });\n}\n\n// Detta skrev jag till AI:n: Jag vill ändra prickarna som kommer när jag klickar med musen. Just nu rör de sig för snabbt och blir otydliga, så jag vill att de ska röra sig långsammare och följa efter musen när jag håller ner knappen. Det ska inte vara för många prickar på en gång, ungefär 25 stycken, och de ska försvinna när jag släpper musknappen. \n//Jag ser tex. att på rad 5 har det lagts till Max mouse dots= 25 som måste ha med detta att göra. jag tycker det blev mycket bättre än innan, för att nu är de tydligare och kommer fram mer långsamt.\n\nfunction drawMouseDots() {\n  if (mouseIsPressed) {\n\n    \n    if (frameCount % 3 === 0 && mouseDots.length < MAX_MOUSE_DOTS) {\n      mouseDots.push({\n        x: mouseX,\n        y: mouseY,\n        offsetX: random(-40, 40),\n        offsetY: random(-40, 40),\n        color: random(DOT_COLORS),\n      });\n    }\n  } else {\n\n    mouseDots = [];\n  }\n\n  noStroke();\n  mouseDots.forEach((d) => {\n    \n    d.x = lerp(d.x, mouseX + d.offsetX, 0.05);\n    d.y = lerp(d.y, mouseY + d.offsetY, 0.05);\n    fill(d.color);\n    circle(d.x, d.y, 30);\n  });\n}\n\n// Den uppdaterade koden är längre än originalet. Jag förstår inte allt som lades till, men jag kan se att en ny loop har lagts till inuti TITLE_LINES.forEach. Originalet gick redan igenom de fyra titelraderna, men nu finns det en andra loop som går igenom bokstäverna i “HYPER”. Jag är inte helt säker på exakt hur den fungerar, men jag tror att den har med vågrörelsen att göra.\nfunction drawText() {\n  const word = 'HYPER';\n \n  const amplitude = mouseIsPressed ? 15 : 6;\n\n  textAlign(LEFT);\n  textSize(60);\n  const totalWidth = textWidth(word);\n\n  TITLE_LINES.forEach((line, row) => {\n    \n    let x = width / 2 - totalWidth / 2;\n\n    for (let i = 0; i < word.length; i++) {\n     \n      const wave = sin(frameCount * 0.1 + i * 0.8 + row * 0.6) * amplitude;\n\n      // Här förstår jag inte riktigt vad som händer, men jag kan se att raderna har något med color och blur att göra. Orden shadowColor och shadowBlur tyder på att det handlar om en skugga, och att den har en färg och är mer eller mindre suddig. Jag ser att färgen hämtas från line.color, så jag tror att skuggan får samma färg som texten på just den raden. DrawingContext är nytt för mig eftersom det inte är något vi använt på lektionerna.\n      \n      drawingContext.shadowBlur = 15 + sin(frameCount * 0.1 + row) * 10;\n      drawingContext.shadowColor = line.color;\n\n      fill(line.color);\n      text(word[i], x, line.y + wave);\n      x += textWidth(word[i]);\n    }\n  });\n\n  drawingContext.shadowBlur = 0;\n\n  textAlign(CENTER);\n  textSize(20);\n  fill('white');\n  text('by Nicole', width / 2, 790);\n}\n\n//AI:ns egna val: Den gjorde titeln till en neontext och gjorde att HYPER rör sig i en våg. Den lade även till att när man håller ner musknappen blir vågen större.\n//Mina åsikter och ändringarna: Ja, jag gillar det verkligen! Den vågande, glödande titeln passar min posters stil eftersom den känns som en neonskylt på en rave. Min poster bygger på starka färger och mycket rörelse från de flytande partiklarna. Tidigare var titeln det enda som stod still. Nu rör sig titeln i en våg och glöden pulserar, så texten känns lika levande som allt runt omkring. \n//Jag gillar också att det är interaktivt. När jag håller ner musknappen blir vågen större samtidigt som prickarna börjar följa muspekaren, hela affischen känns mer energisk och “hyper”, precis som titeln säger. ", "assets": {"colorpicture.jpg": {"mime": "image/webp", "b64": ""}, "ravebild.jpg": {"mime": "image/webp", "b64": ""}}});
